// Versling worker: serves the static site via the ASSETS binding, and for
// deep-linked verse URLs (?v=surah:ayah) rewrites the page's <title> and
// og:/twitter: meta tags to the real verse text before the response goes out.
//
// Why this exists: the app already builds and shares real ?v=surah:ayah
// links (see public/app.js verseUrl/updateUrlForGi), but the static HTML
// always carried the same generic title/description for every URL. Social
// apps and iMessage/WhatsApp link previews are generated by crawlers that
// don't execute client JS, so every shared verse link showed the same
// generic "Versling — Quran, one verse at a time" card instead of the
// actual verse — undermining the point of sharing a specific verse.

function parseVerseRef(raw) {
  if (!raw) return null;
  const m = /^(\d{1,3}):(\d{1,3})$/.exec(String(raw).trim());
  if (!m) return null;
  return { surah: parseInt(m[1], 10), ayah: parseInt(m[2], 10) };
}

function truncate(s, n) {
  return s.length > n ? s.slice(0, n).trim() + "…" : s;
}

async function fetchJson(env, url, pathname) {
  const assetUrl = new URL(pathname, url);
  const res = await env.ASSETS.fetch(new Request(assetUrl));
  if (!res.ok) return null;
  try {
    return await res.json();
  } catch {
    return null;
  }
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const ref = parseVerseRef(url.searchParams.get("v"));

    // No deep-link param, or asset/data/API requests: serve as-is.
    if (!ref || url.pathname !== "/") {
      return env.ASSETS.fetch(request);
    }

    try {
      const surahs = await fetchJson(env, url, "/data/surahs.json");
      const info = surahs && surahs[ref.surah - 1];
      if (!info || info.number !== ref.surah || ref.ayah < 1 || ref.ayah > info.ayahCount) {
        return env.ASSETS.fetch(request);
      }

      const verses = await fetchJson(env, url, `/data/surah-${ref.surah}.json`);
      const verse = verses && verses[ref.ayah - 1];
      if (!verse || !verse.translation) {
        return env.ASSETS.fetch(request);
      }

      const pageRes = await env.ASSETS.fetch(request);
      const contentType = pageRes.headers.get("content-type") || "";
      if (!pageRes.ok || !contentType.includes("text/html")) {
        return pageRes;
      }

      const title = `Quran ${ref.surah}:${ref.ayah} — ${info.nameEnglish} | Versling`;
      const description = truncate(verse.translation, 180);
      const pageUrl = `${url.origin}${url.pathname}?v=${ref.surah}:${ref.ayah}`;

      const rewriter = new HTMLRewriter()
        .on("title", { element(el) { el.setInnerContent(title); } })
        .on('meta[name="description"]', { element(el) { el.setAttribute("content", description); } })
        .on('meta[property="og:title"]', { element(el) { el.setAttribute("content", title); } })
        .on('meta[property="og:description"]', { element(el) { el.setAttribute("content", description); } })
        .on('meta[property="og:url"]', { element(el) { el.setAttribute("content", pageUrl); } })
        .on('meta[name="twitter:title"]', { element(el) { el.setAttribute("content", title); } })
        .on('meta[name="twitter:description"]', { element(el) { el.setAttribute("content", description); } });

      return rewriter.transform(pageRes);
    } catch {
      // Any failure in the lookup path falls back to the plain static page —
      // never break the actual app over a preview-card nicety.
      return env.ASSETS.fetch(request);
    }
  },
};
